        assertThat(path.get()).isEqualTo("/v1/authorizations");
        assertThat(contentType.get()).startsWith("application/json");
        assertThat(body.get()).isEqualTo("{\"reference\":\"ORD-7\",\"amount\":12.50,\"currency\":\"EUR\"}");
    }

    @Test
    void an_approved_answer_is_read_as_approved() {
        assertThat(authorizeWith(200, "{\"status\":\"approved\"}")).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_answer_is_read_as_declined() {
        assertThat(authorizeWith(200, "{\"status\":\"declined\"}")).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void unknown_fields_in_the_answer_are_ignored() {
        assertThat(authorizeWith(200, "{\"id\":\"a1\",\"status\":\"approved\",\"extra\":{\"x\":1}}"))
                .isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void an_unrecognised_status_is_never_treated_as_approved() {
        assertThat(authorizeWith(200, "{\"status\":\"pending\"}")).isEqualTo(AuthorizationOutcome.DECLINED);
        assertThat(authorizeWith(200, "{\"state\":\"approved\"}")).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_refusal_with_402_is_read_as_declined() {
        assertThat(authorizeWith(402, "{\"error\":\"card_refused\"}")).isEqualTo(AuthorizationOutcome.DECLINED);
        assertThat(authorizeWith(402, "")).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_is_declined_even_if_the_body_claims_approval() {
        assertThat(authorizeWith(402, "{\"status\":\"approved\"}")).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void other_error_statuses_are_reported_as_failures_not_declines() {
        for (var code : new int[] {400, 401, 500, 503}) {
            assertThatThrownBy(() -> authorizeWith(code, "{\"error\":\"boom\"}"))
                    .isInstanceOf(IllegalStateException.class)
                    .hasMessageContaining(String.valueOf(code));
        }
    }
}
